import type { BankQuestion } from "@/lib/bank";

/** General Organic Chemistry (Chemistry (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-goc-1","question":"The IUPAC name of CH₃–CH(CH₃)–CH₂–CH₃ is:","options":["Isobutane","2-Methylbutane","3-Methylbutane","Pentane"],"answer":1,"explanation":"The longest chain has four carbons (butane) with a methyl branch; numbering from the end nearer the branch gives position 2, so 2-methylbutane. 3-Methylbutane violates the lowest-locant rule.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-goc-2","question":"Which group exerts the strongest −I (electron-withdrawing inductive) effect?","options":["–CH₃","–OCH₃","–NO₂","–Cl"],"answer":2,"explanation":"The −I order is –NR₃⁺ > –NO₂ > –CN > –COOH > –F > –Cl > –Br > –I > –OCH₃. –CH₃ is a +I group.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-goc-3","question":"Homolytic fission of a covalent bond produces:","options":["A carbocation and a carbanion","Two free radicals","Two carbanions","A carbene"],"answer":1,"explanation":"In homolysis each atom keeps one electron of the shared pair, giving two neutral species with unpaired electrons (free radicals). Heterolysis gives an ion pair.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-goc-4","question":"The number of structural (chain) isomers of C₅H₁₂ is:","options":["3","4","5","2"],"answer":0,"explanation":"Pentane, 2-methylbutane and 2,2-dimethylpropane: three isomers. C₆H₁₄ has five and C₇H₁₆ has nine.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-goc-5","question":"Which carbocation is the most stable?","options":["CH₃⁺","CH₃CH₂⁺","(CH₃)₂CH⁺","(CH₃)₃C⁺"],"answer":3,"explanation":"Stability increases with the number of alkyl groups on the positive carbon (+I effect and hyperconjugation): 3° > 2° > 1° > CH₃⁺. The tert-butyl cation has nine α-hydrogens for hyperconjugation.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-goc-6","question":"Which of the following compounds is chiral (optically active)?","options":["2-Chloropropane","2-Chlorobutane","1-Chlorobutane","2-Chloro-2-methylpropane"],"answer":1,"explanation":"C2 of 2-chlorobutane carries four different groups (H, Cl, CH₃, C₂H₅) and is a stereocentre. In the other molecules the carbon bearing Cl has at least two identical groups.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-goc-7","question":"Which acid is the strongest?","options":["CH₃COOH","ClCH₂COOH","Cl₂CHCOOH","Cl₃CCOOH"],"answer":3,"explanation":"Each additional −I chlorine disperses the negative charge of the carboxylate anion more, so acidity increases: Cl₃CCOOH (pKa ≈ 0.7) > Cl₂CHCOOH > ClCH₂COOH > CH₃COOH (pKa 4.76).","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-goc-8","question":"Which alkene shows the maximum hyperconjugation?","options":["Propene","But-2-ene","2-Methylpropene","2,3-Dimethylbut-2-ene"],"answer":3,"explanation":"Hyperconjugation in alkenes depends on the number of α-hydrogens (C–H bonds on carbons attached to the double bond): propene 3, but-2-ene 6, 2-methylpropene 6, 2,3-dimethylbut-2-ene 12. More α-H means more stabilisation (Saytzeff rule).","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-goc-9","question":"Which of the following is an electrophile?","options":["NH₃","H₂O","BF₃","CN⁻"],"answer":2,"explanation":"BF₃ is electron-deficient (boron has only six electrons) and accepts an electron pair, so it is an electrophile (Lewis acid). NH₃, H₂O and CN⁻ have lone pairs and act as nucleophiles.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-goc-10","question":"The IUPAC name of CH₃–CO–CH₂–CH₂–COOH is:","options":["2-Oxopentanoic acid","4-Oxopentanoic acid","Pentan-2-one-5-oic acid","4-Ketopentanoic acid"],"answer":1,"explanation":"The carboxylic acid is the principal group, so C1 is COOH; the keto group is then on C4 and is named as the prefix 'oxo': 4-oxopentanoic acid. 'Keto' is not an IUPAC prefix.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-11","question":"In aqueous solution, the strongest base among the following is:","options":["NH₃","CH₃NH₂","(CH₃)₂NH","(CH₃)₃N"],"answer":2,"explanation":"In water the order is (CH₃)₂NH > CH₃NH₂ > (CH₃)₃N > NH₃. The +I effect raises basicity, but the tertiary amine's conjugate acid is poorly solvated (fewer N–H bonds, more steric hindrance), so trimethylamine drops below the primary amine.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-12","question":"The correct decreasing order of acidity is:","options":["p-Nitrophenol > m-nitrophenol > phenol > p-cresol","m-Nitrophenol > p-nitrophenol > p-cresol > phenol","p-Cresol > phenol > m-nitrophenol > p-nitrophenol","p-Nitrophenol > phenol > m-nitrophenol > p-cresol"],"answer":0,"explanation":"–NO₂ at para delocalises the phenoxide charge by resonance (−R and −I), at meta only −I operates, so p-nitrophenol > m-nitrophenol > phenol. –CH₃ (+I) destabilises the anion, making p-cresol weaker than phenol.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-13","question":"The number of stereoisomers of butane-2,3-diol, CH₃–CH(OH)–CH(OH)–CH₃, is:","options":["3","4","6","2"],"answer":0,"explanation":"The two stereocentres are identical, so of the 2² = 4 combinations, (R,S) and (S,R) are the same meso compound. Stereoisomers = one meso form + the (R,R)/(S,S) enantiomeric pair = 3.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-14","question":"Which carbanion is the most stable?","options":["CH₃CH₂⁻","(CH₃)₃C⁻","CH₂=CH–CH₂⁻","C₆H₅CH₂⁻"],"answer":3,"explanation":"Carbanions are stabilised by delocalisation. The benzyl carbanion's charge spreads over the ring (four resonance structures), more than the allyl anion's (two). Alkyl groups (+I) destabilise carbanions, so (CH₃)₃C⁻ is the least stable.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-15","question":"Which of the following alkenes shows geometrical (cis–trans) isomerism?","options":["2-Methylbut-2-ene","Pent-1-ene","Pent-2-ene","2-Methylpropene"],"answer":2,"explanation":"Geometrical isomerism needs two different groups on each doubly bonded carbon. In pent-2-ene, CH₃–CH=CH–C₂H₅, each alkene carbon carries H and an alkyl group. 2-Methylbut-2-ene has two CH₃ on one carbon, and the terminal alkenes have two H on one carbon.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-16","question":"Which is the correct order of decreasing −I effect?","options":["–F > –NO₂ > –CN > –NR₃⁺","–NR₃⁺ > –NO₂ > –CN > –F","–NO₂ > –NR₃⁺ > –F > –CN","–CN > –NO₂ > –F > –NR₃⁺"],"answer":1,"explanation":"A full positive charge on nitrogen makes –NR₃⁺ the strongest −I group, followed by –NO₂, –CN, then the halogens (–F > –Cl > –Br > –I).","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-17","question":"The primary carbocation (CH₃)₂CH–CH₂⁺ rearranges to a more stable tertiary carbocation by:","options":["A 1,2-methyl shift","A 1,2-hydride shift","Ring expansion","Loss of a proton"],"answer":1,"explanation":"A hydrogen on the adjacent (tertiary) carbon migrates with its bonding pair to the cationic carbon, giving (CH₃)₃C⁺. A methyl shift would give a secondary cation, which is less stable.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-18","question":"In (Z)-1-bromo-1-chloropropene, CHBr(Cl)=CH–CH₃, which groups lie on the same side of the double bond?","options":["Br and H","Cl and CH₃","Br and CH₃","Cl and H"],"answer":2,"explanation":"By CIP priority, Br > Cl on C1 and CH₃ > H on C2. Z (zusammen) means the higher-priority groups, Br and CH₃, are on the same side; E would have Br and H together.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-19","question":"How many of the following statements are correct? (i) Resonance structures differ only in the positions of electrons, not of atoms. (ii) Hyperconjugation is also called no-bond resonance. (iii) The tert-butyl carbanion is more stable than the methyl carbanion. (iv) Free radicals are paramagnetic.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iv) are correct. (iii) is wrong: the +I effect of methyl groups intensifies the negative charge, so CH₃⁻ is more stable than (CH₃)₃C⁻ (the opposite of carbocation order).","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-20","question":"Arrange in increasing order of pKa: phenol (I), o-nitrophenol (II), m-nitrophenol (III), p-nitrophenol (IV).","options":["I < III < II < IV","IV < III < II < I","IV < II < III < I","II < IV < III < I"],"answer":2,"explanation":"Lower pKa means stronger acid. p-Nitrophenol (pKa ≈ 7.1) is slightly stronger than the ortho isomer (≈ 7.2) because intramolecular H-bonding in o-nitrophenol stabilises the undissociated acid; both beat the meta isomer (≈ 8.4, −I only) and phenol (≈ 10).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-21","question":"The number of stereoisomers of 2,3-dibromopentane, CH₃–CHBr–CHBr–CH₂CH₃, is:","options":["2","3","4","8"],"answer":2,"explanation":"The two stereocentres carry different sets of groups (one has CH₃, the other C₂H₅), so no meso form exists and all 2² = 4 stereoisomers (two enantiomeric pairs) are distinct. Compare butane-2,3-diol, which has only 3.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-22","question":"Assertion (A): Aniline is a much weaker base than cyclohexylamine. Reason (R): The lone pair on the nitrogen of aniline is delocalised into the benzene ring by resonance.","options":["A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Delocalisation makes the nitrogen lone pair in aniline less available for protonation (pKb ≈ 9.4) than in cyclohexylamine (pKb ≈ 3.3), where the lone pair is localised on an sp³ nitrogen. R is the correct reason.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-23","question":"Match the substituent on a benzene ring with its electronic effects. (A) –OCH₃; (B) –NO₂; (C) –Cl; (D) –CH₃. (p) −I and −R, meta-directing; (q) +I and hyperconjugation, ortho/para-directing; (r) −I stronger than +R, deactivating but ortho/para-directing; (s) +R stronger than −I, activating, ortho/para-directing.","options":["A–s, B–p, C–r, D–q","A–r, B–p, C–s, D–q","A–s, B–r, C–p, D–q","A–q, B–p, C–r, D–s"],"answer":0,"explanation":"–OCH₃ donates by resonance (+R > −I) and activates o/p positions; –NO₂ withdraws by both effects and directs meta; halogens are unusual: −I dominates (deactivating) but +R directs o/p; –CH₃ activates by +I and hyperconjugation.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-24","question":"The IUPAC name of CH₃–CH=CH–CH₂–CHO is:","options":["Pent-3-enal","Pent-4-enal","2-Pentenal","Pent-2-enal"],"answer":0,"explanation":"The aldehyde carbon is always C1, so numbering runs CHO (1), CH₂ (2), CH (3), CH (4), CH₃ (5): the double bond starts at C3, giving pent-3-enal. Numbering from the CH₃ end to give the double bond locant 2 is wrong because the principal group must get the lowest number.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-25","question":"Which of the following anions is the weakest base?","options":["CH₃CH₂⁻","CH₂=CH⁻","HC≡C⁻","NH₂⁻"],"answer":2,"explanation":"The weakest base is the conjugate base of the strongest acid. Acidity: ethyne (pKa ≈ 25) > NH₃ (≈ 38) > ethene (≈ 44) > ethane (≈ 50), because the sp carbon (50% s-character) holds the negative charge best. Hence HC≡C⁻ is the weakest base.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-26","question":"Which of the following species is aromatic?","options":["Cyclopropenyl anion","Cyclopentadienyl anion","Cycloheptatrienyl anion","Cyclooctatetraene"],"answer":1,"explanation":"Aromaticity needs a planar, cyclic, fully conjugated system with (4n + 2) π electrons. The cyclopentadienyl anion has 6 π electrons. The cyclopropenyl anion (4 π) and cycloheptatrienyl anion (8 π) are antiaromatic, and cyclooctatetraene (8 π) is non-planar and non-aromatic.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-27","question":"Among the following, the most stable carbocation is:","options":["Vinyl cation, CH₂=CH⁺","Phenyl cation, C₆H₅⁺","Cyclopropylmethyl cation","Ethyl cation, CH₃CH₂⁺"],"answer":2,"explanation":"The cyclopropylmethyl cation is exceptionally stable because the bent (banana) C–C bonds of the ring overlap with the empty p-orbital. Vinyl and phenyl cations are very unstable: the positive charge sits in an sp² (or sp) orbital that cannot be delocalised by the π system.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-goc-28","question":"How many isomeric ethers have the molecular formula C₄H₁₀O?","options":["2","3","4","7"],"answer":1,"explanation":"Ethoxyethane, 1-methoxypropane and 2-methoxypropane: three ethers. C₄H₁₀O also has four alcohols (butan-1-ol, butan-2-ol, 2-methylpropan-1-ol, 2-methylpropan-2-ol), making seven isomers in all.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-29","question":"How many of the following statements about conformations are correct? (i) The anti conformer of butane is its most stable conformation. (ii) The gauche conformer of butane has a dihedral angle of 60° between the methyl groups. (iii) The eclipsed conformation of ethane is more stable than the staggered. (iv) The conformers of ethane cannot be isolated at room temperature.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iv) are correct. (iii) is wrong: the staggered form is more stable by about 12.5 kJ mol⁻¹ (torsional strain is minimum); this barrier is too small to prevent rapid interconversion, so conformers cannot be separated.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-30","question":"Which statement about carbanions is INCORRECT?","options":["A simple alkyl carbanion is pyramidal with an sp³-hybridised carbon","Carbanions act as nucleophiles","Electron-withdrawing groups on the α-carbon stabilise a carbanion","(CH₃)₃C⁻ is more stable than CH₃⁻"],"answer":3,"explanation":"Alkyl groups donate electron density (+I), which intensifies the negative charge; hence CH₃⁻ > 1° > 2° > 3° in carbanion stability, the reverse of carbocations. The other three statements are correct.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-31","question":"Which of the following is a nucleophile?","options":["NO₂⁺","NH₃","BF₃","AlCl₃"],"answer":1,"explanation":"NH₃ has a lone pair to donate. BF₃, AlCl₃ (electron-deficient) and NO₂⁺ (cation) are electrophiles.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-goc-32","question":"Which alkyl group shows the strongest +I (electron-releasing inductive) effect?","options":["(CH₃)₂CH–","CH₃–","(CH₃)₃C–","CH₃CH₂–"],"answer":2,"explanation":"+I increases with the number of alkyl groups on the attached carbon: tert-butyl > isopropyl > ethyl > methyl.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-goc-33","question":"The number of sp²-hybridised carbon atoms in CH₂=CH–CHO is:","options":["3","2","0","1"],"answer":0,"explanation":"Both alkene carbons and the carbonyl carbon form a π bond, so all three carbons are sp².","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-goc-34","question":"Diethyl ether and methyl propyl ether are an example of:","options":["Position isomerism","Chain isomerism","Functional isomerism","Metamerism"],"answer":3,"explanation":"Both are C₄H₁₀O ethers that differ in the alkyl groups on either side of the same functional group — metamerism.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-goc-35","question":"The IUPAC name of CH₃–CH(Cl)–CH₂–COOH is:","options":["3-Chlorobutanoic acid","2-Chlorobutanoic acid","3-Chlorobutan-1-oic acid","1-Carboxy-2-chloropropane"],"answer":0,"explanation":"Numbering starts from the COOH carbon (C1); Cl is on C3 of the four-carbon chain.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-36","question":"Which free radical is the most stable?","options":["CH₂=CH•","CH₃•","(CH₃)₃C•","C₆H₅CH₂•"],"answer":3,"explanation":"The benzyl radical is resonance-stabilised over the ring, more than the hyperconjugation in tert-butyl. The vinyl radical is very unstable.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-37","question":"The number of geometrical isomers of hepta-2,5-diene, CH₃–CH=CH–CH₂–CH=CH–CH₃, is:","options":["6","3","4","2"],"answer":1,"explanation":"Each double bond can be E or Z, giving 4 combinations, but the molecule is symmetrical so E,Z and Z,E are the same: EE, ZZ and EZ = 3.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-38","question":"Which of the following shows keto–enol tautomerism?","options":["Propanone","Benzaldehyde","Methanal","2,2-Dimethylpropanal"],"answer":0,"explanation":"Tautomerism needs an α-hydrogen. Propanone has six; benzaldehyde, 2,2-dimethylpropanal and methanal have none.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-39","question":"How many of the following statements are correct? (A) The electromeric effect is temporary and operates only in the presence of an attacking reagent. (B) Hyperconjugation in the ethyl cation involves the C–H σ bonds of the methyl group. (C) The –OH group attached to benzene shows −I and +R effects. (D) Resonance energy is the difference between the energy of the most stable contributing structure and that of the actual hybrid.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The hybrid is always lower in energy than any contributing structure, and that gap is the resonance energy.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-40","question":"The correct order of basicity is:","options":["NH₃ > CH₃NH₂ > guanidine > C₆H₅NH₂","Guanidine > CH₃NH₂ > NH₃ > C₆H₅NH₂","CH₃NH₂ > guanidine > NH₃ > C₆H₅NH₂","C₆H₅NH₂ > NH₃ > CH₃NH₂ > guanidine"],"answer":1,"explanation":"The guanidinium ion is stabilised by three equivalent resonance structures (pKa ≈ 13.6). Methylamine (+I) beats NH₃, and aniline's lone pair is delocalised into the ring.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-41","question":"How many of the following are aromatic: benzene, cyclooctatetraene, cyclopentadienyl cation, tropylium cation, pyridine, furan, cyclobutadiene?","options":["4","5","6","3"],"answer":0,"explanation":"Benzene, tropylium (6π), pyridine and furan (6π, O lone pair) are aromatic. Cyclooctatetraene is tub-shaped and non-aromatic; the cyclopentadienyl cation (4π) and cyclobutadiene are antiaromatic.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-42","question":"The correct order of acidic strength among H₂O, NH₃, HC≡CH and CH₂=CH₂ is:","options":["NH₃ > H₂O > CH₂=CH₂ > HC≡CH","H₂O > NH₃ > HC≡CH > CH₂=CH₂","HC≡CH > H₂O > NH₃ > CH₂=CH₂","H₂O > HC≡CH > NH₃ > CH₂=CH₂"],"answer":3,"explanation":"Approximate pKa: H₂O 15.7, ethyne 25, NH₃ 38, ethene 44. That is why NaNH₂ deprotonates ethyne, while water protonates acetylide.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-43","question":"Assertion (A): o-Toluic acid (2-methylbenzoic acid) is a stronger acid than benzoic acid. Reason (R): The ortho substituent twists the –COOH group out of the plane of the ring, reducing resonance of the ring with the carboxyl group (ortho effect).","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both true and R explains A: steric inhibition of resonance makes almost any ortho-substituted benzoic acid stronger than benzoic acid, even when the group is electron-releasing.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-goc-44","question":"3-Methylbutan-2-ol is treated with HBr. The major product is:","options":["1-Bromo-3-methylbutane","1-Bromo-2-methylbutane","2-Bromo-3-methylbutane","2-Bromo-2-methylbutane"],"answer":3,"explanation":"Protonation and loss of water give a secondary carbocation at C2, which undergoes a 1,2-hydride shift to the tertiary C3 cation; Br⁻ then attacks there.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-45","question":"The total number of stereoisomers of 4-bromopent-2-ene, CH₃–CH=CH–CH(Br)–CH₃, is:","options":["4","6","3","2"],"answer":0,"explanation":"The C=C can be E or Z and C4 is a chiral centre (R or S). The two elements are independent and the molecule is unsymmetrical: 2 × 2 = 4.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-goc-46", "question": "In propene, CH₂=CH–CH₃, the hybridisations of C1, C2 and C3 are respectively:", "options": ["sp³, sp², sp²", "sp², sp², sp³", "sp², sp, sp³", "sp², sp², sp²"], "answer": 1, "explanation": "The two doubly bonded carbons (C1 and C2) are sp²; the methyl carbon (C3) has four single bonds and is sp³.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-goc-47", "question": "The IUPAC name of CH₃CH₂CHO is:", "options": ["Propanone", "Ethanal", "Propan-1-al", "Propanal"], "answer": 3, "explanation": "Three carbons with the –CHO group at C1: propanal. The aldehyde carbon is always C1, so no locant is written. Propanone is the ketone CH₃COCH₃.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-goc-48", "question": "The IUPAC name of CH₂=CH–CH₂–OH is:", "options": ["Prop-1-en-3-ol", "Prop-2-en-1-ol", "Propenal", "Propan-2-en-1-ol"], "answer": 1, "explanation": "The principal group –OH gets the lowest locant (C1), so the double bond is between C2 and C3: prop-2-en-1-ol (allyl alcohol). Prop-1-en-3-ol numbers from the wrong end.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-goc-49", "question": "The number of hyperconjugative (α) hydrogens available to stabilise the isopropyl cation, (CH₃)₂CH⁺, is:", "options": ["7", "3", "6", "9"], "answer": 2, "explanation": "Only C–H bonds on carbons adjacent to the positive carbon can overlap with its empty p orbital: two CH₃ groups give 6 such hydrogens. The H on the cationic carbon itself does not count.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-goc-50", "question": "Which of the following groups attached to a benzene ring shows a +R (electron-releasing resonance) effect?", "options": ["–CHO", "–NO₂", "–CN", "–Cl"], "answer": 3, "explanation": "–Cl has lone pairs that it can donate into the ring (+R), although its −I effect is stronger overall. –CHO, –NO₂ and –CN withdraw electrons from the ring by resonance (−R).", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-goc-51", "question": "In 2,2,4-trimethylpentane, (CH₃)₃C–CH₂–CH(CH₃)–CH₃, the numbers of primary, secondary, tertiary and quaternary carbon atoms are respectively:", "options": ["4, 2, 1, 1", "5, 2, 1, 0", "5, 1, 1, 1", "6, 0, 1, 1"], "answer": 2, "explanation": "Primary: the five CH₃ groups. Secondary: the single CH₂. Tertiary: the CH bearing a methyl. Quaternary: C2, bonded to four carbons. So 5, 1, 1, 1 (8 carbons in all).", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-goc-52", "question": "Which of the following pairs are position isomers?", "options": ["Butan-1-ol and butan-2-ol", "Ethanol and methoxymethane", "Diethyl ether and methyl propyl ether", "Pentane and 2-methylbutane"], "answer": 0, "explanation": "Butan-1-ol and butan-2-ol have the same chain and functional group but differ in where –OH sits. Ethanol/methoxymethane are functional isomers, the ethers are metamers and pentane/2-methylbutane are chain isomers.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-goc-53", "question": "In but-1-ene, CH₂=CH–CH₂–CH₃, which C–H bond has the lowest bond dissociation enthalpy?", "options": ["A C–H bond on C1", "A C–H bond on C2", "A C–H bond on C3", "A C–H bond on C4"], "answer": 2, "explanation": "Breaking a C3–H bond gives an allylic radical stabilised by resonance with the double bond, so this bond is the weakest. Vinylic C–H bonds (C1, C2) are the strongest; the C4 (primary) C–H gives an unstabilised radical.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-54", "question": "Which of the following compounds has the highest percentage of enol form at equilibrium?", "options": ["Acetone, CH₃COCH₃", "Pentane-2,4-dione, CH₃COCH₂COCH₃", "Ethyl acetoacetate, CH₃COCH₂COOC₂H₅", "Cyclohexanone"], "answer": 1, "explanation": "The enol of pentane-2,4-dione is conjugated with the second C=O and held by an intramolecular hydrogen bond (six-membered ring), so it is about 76–80% enol in the pure liquid. Ethyl acetoacetate is less enolised (the ester C=O is a weaker acceptor), and simple ketones are almost entirely keto.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-55", "question": "Which resonance structure contributes LEAST to the hybrid of propenal (acrolein), CH₂=CH–CH=O?", "options": ["CH₂=CH–CH=O", "⁺CH₂–CH=CH–O⁻", "⁻CH₂–CH=CH–O⁺", "CH₂=CH–C⁺H–O⁻"], "answer": 2, "explanation": "Structures with the negative charge on the more electronegative atom (O) are reasonable. ⁻CH₂–CH=CH–O⁺ puts a positive charge on oxygen, which then has an incomplete octet, and a negative charge on carbon, so it contributes almost nothing. The neutral structure contributes most.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-56", "question": "Which of the following alkenes has the least negative enthalpy of hydrogenation?", "options": ["But-1-ene", "cis-But-2-ene", "trans-But-2-ene", "2-Methylpropene"], "answer": 2, "explanation": "All four give butane or isobutane with similar product energies, so the most stable alkene releases the least heat. trans-But-2-ene (≈ −116 kJ/mol) is disubstituted and free of the cis steric strain; cis-but-2-ene ≈ −120, 2-methylpropene ≈ −119 and but-1-ene ≈ −127 kJ/mol.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-goc-57", "question": "Which of the following compounds is chiral although it has no stereocentre (chiral carbon atom)?", "options": ["Buta-1,2-diene", "Propadiene", "3-Methylbuta-1,2-diene", "Penta-2,3-diene"], "answer": 3, "explanation": "In an allene the substituents at the two ends lie in perpendicular planes. CH₃CH=C=CHCH₃ has two different groups (H and CH₃) at each end, so it has non-superimposable mirror images (axial chirality). The other allenes have two identical groups at one end.", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id": "chem-goc-58", "question": "The correct order of nucleophilicity of the halide ions in a polar protic solvent such as water or methanol is:", "options": ["F⁻ > Cl⁻ > Br⁻ > I⁻", "I⁻ > Br⁻ > Cl⁻ > F⁻", "Cl⁻ > F⁻ > Br⁻ > I⁻", "Br⁻ > I⁻ > Cl⁻ > F⁻"], "answer": 1, "explanation": "In protic solvents small F⁻ is strongly solvated by hydrogen bonding and its lone pairs are held tightly; large, polarisable I⁻ is weakly solvated and is the best nucleophile. In polar aprotic solvents the order tends to reverse.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-59", "question": "Which of the following is an ambident nucleophile, able to attack through two different atoms?", "options": ["OH⁻", "Cl⁻", "CN⁻", "NH₃"], "answer": 2, "explanation": "Cyanide can attack through carbon (giving nitriles, R–CN) or through nitrogen (giving isocyanides, R–NC, e.g. with AgCN). Nitrite (NO₂⁻) is another example.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-60", "question": "How many of the following statements are correct? (A) Tautomers are structural isomers that exist in dynamic equilibrium. (B) Resonance structures are in dynamic equilibrium with one another. (C) Keto–enol tautomerism of a carbonyl compound requires at least one α-hydrogen. (D) Phenol exists mainly in its keto form.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(A) and (C) are correct. (B) is false: resonance structures are not real species and do not interconvert; the molecule is a single hybrid. (D) is false: the enol (phenol) form is overwhelmingly favoured because it keeps the aromatic ring. Two are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-61", "question": "The correct decreasing order of acidic strength is:", "options": ["C₆H₅OH > CH₃COOH > H₂O > C₂H₅OH > HC≡CH", "CH₃COOH > C₆H₅OH > C₂H₅OH > H₂O > HC≡CH", "CH₃COOH > C₆H₅OH > H₂O > C₂H₅OH > HC≡CH", "CH₃COOH > H₂O > C₆H₅OH > HC≡CH > C₂H₅OH"], "answer": 2, "explanation": "Approximate pKa: acetic acid 4.8 (carboxylate has two equivalent resonance forms), phenol 10 (phenoxide delocalised into the ring), water 15.7, ethanol about 16 (+I of the ethyl group destabilises ethoxide) and ethyne 25.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-62", "question": "The correct order of basic strength is:", "options": ["Pyridine > piperidine > aniline > pyrrole", "Piperidine > aniline > pyridine > pyrrole", "Pyrrole > pyridine > piperidine > aniline", "Piperidine > pyridine > aniline > pyrrole"], "answer": 3, "explanation": "Piperidine is an sp³ secondary amine (pKb ≈ 2.9). Pyridine's lone pair is in an sp² orbital, held more tightly (pKb ≈ 8.8). Aniline's lone pair is partly delocalised into the ring (pKb ≈ 9.4). Pyrrole's lone pair is part of its aromatic sextet, so it is hardly basic at all.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-goc-63", "question": "The total number of stereoisomers of 1,2-dimethylcyclohexane is:", "options": ["2", "3", "4", "1"], "answer": 1, "explanation": "There are two stereocentres (C1 and C2) with identical substituents. The cis isomer has a plane of symmetry in its averaged structure and is meso (optically inactive); the trans isomer exists as a pair of enantiomers. Total = 1 + 2 = 3.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-goc-64", "question": "Assertion (A): Tropylium bromide, C₇H₇Br, is an ionic solid that dissolves in water. Reason (R): The cycloheptatrienyl (tropylium) cation is aromatic, with 6 π electrons delocalised over a planar ring of seven carbon atoms.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because C₇H₇⁺ obeys Hückel's rule (4n + 2 = 6, n = 1), it is unusually stable, so the C–Br bond ionises completely to give C₇H₇⁺ Br⁻. R correctly explains A.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-goc-65", "question": "Match the reactive intermediate (Column I) with its description (Column II). (a) CH₃⁺, (b) CH₃⁻, (c) CH₃•, (d) singlet :CH₂. (1) sp³, pyramidal, octet complete; (2) sp², planar, six valence electrons and no lone pair; (3) sp², bent, six valence electrons including a lone pair; (4) planar (or nearly so), seven valence electrons.", "options": ["a-2, b-1, c-3, d-4", "a-2, b-1, c-4, d-3", "a-4, b-1, c-2, d-3", "a-1, b-2, c-4, d-3"], "answer": 1, "explanation": "Methyl carbocation: sp², planar, 6 electrons. Methyl carbanion: sp³ with a lone pair, pyramidal, 8 electrons. Methyl radical: planar (or almost), 7 electrons. Singlet carbene: sp², bent, with a lone pair and an empty p orbital (6 electrons). So a-2, b-1, c-4, d-3.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-goc-66", "question": "The IUPAC name of CH₃–CH(C₂H₅)–CH₂–CH(CH₃)–CH₃ is:", "options": ["2-Ethyl-4-methylpentane", "2,4-Dimethylhexane", "3,5-Dimethylhexane", "4-Ethyl-2-methylpentane"], "answer": 1, "explanation": "The longest chain runs through the ethyl group: CH₃–CH₂–CH(CH₃)–CH₂–CH(CH₃)–CH₃, six carbons. Numbering from the end nearer the first branch gives methyls at C2 and C4: 2,4-dimethylhexane. An ethyl group at C2 is a sure sign the longest chain was missed.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-67", "question": "The IUPAC name of OHC–CH(OH)–CH₂–COOH is:", "options": ["2-Hydroxy-4-carboxybutanal", "3-Formyl-3-hydroxypropanoic acid", "3-Hydroxy-4-oxobutanoic acid", "4-Hydroxy-1-oxobutanoic acid"], "answer": 2, "explanation": "–COOH has the highest priority, so its carbon is C1 and the parent is butanoic acid. –OH at C3 and the terminal –CHO at C4 (written as oxo, since its carbon is in the chain) are prefixes in alphabetical order: 3-hydroxy-4-oxobutanoic acid.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-68", "question": "How many of the following are electrophiles: BF₃, NO₂⁺, H₂O, CN⁻, AlCl₃, (CH₃)₃C⁺, NH₃, SO₃?", "options": ["4", "5", "6", "3"], "answer": 1, "explanation": "Electrophiles are electron-deficient species: BF₃ and AlCl₃ (incomplete octets), NO₂⁺ and (CH₃)₃C⁺ (positive), and SO₃ (strongly electron-poor sulphur, the electrophile in sulphonation): 5. H₂O, CN⁻ and NH₃ donate lone pairs and are nucleophiles.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-69", "question": "How many of the following statements are correct? (A) A meso compound is optically inactive even though it contains stereocentres. (B) Enantiomers have identical physical properties except for the direction in which they rotate plane-polarised light. (C) Diastereomers have identical boiling points. (D) A racemic mixture is optically inactive because of external compensation.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(A) true (internal compensation by a plane of symmetry). (B) true (in an achiral environment). (C) false: diastereomers are not mirror images and have different physical properties. (D) true: equal amounts of the two enantiomers cancel each other's rotation. Three are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-goc-70", "question": "Which of the following compounds has the most acidic C–H hydrogen?", "options": ["Acetone, CH₃COCH₃", "Diethyl malonate, CH₂(COOC₂H₅)₂", "Pentane-2,4-dione, CH₃COCH₂COCH₃", "Acetonitrile, CH₃CN"], "answer": 2, "explanation": "The CH₂ between two ketone groups (pKa ≈ 9) gives a carbanion delocalised over both C=O groups. Diethyl malonate (≈ 13) is weaker because the ester groups' alkoxy oxygen donates electrons; acetone (≈ 19–20) has only one C=O and acetonitrile (≈ 25) only a C≡N.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-goc-71", "question": "The degree of unsaturation (double-bond equivalent) of cinnamonitrile, C₆H₅–CH=CH–C≡N, is:", "options": ["6", "5", "7", "8"], "answer": 2, "explanation": "C₉H₇N: DBE = (2C + 2 + N − H)/2 = (18 + 2 + 1 − 7)/2 = 7. Check: benzene ring 4 (one ring + three C=C), C=C 1, C≡N 2. Forgetting to add the nitrogen gives 6.5, and counting C≡N as 1 gives 6.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-goc-72", "question": "Which benzylic carbocation is the most stable?", "options": ["p-CH₃O–C₆H₄–CH₂⁺", "p-O₂N–C₆H₄–CH₂⁺", "p-Cl–C₆H₄–CH₂⁺", "C₆H₅–CH₂⁺"], "answer": 0, "explanation": "The para-OCH₃ group donates its lone pair by resonance (+R) right onto the benzylic carbon, giving a structure with all atoms having octets. Cl withdraws more by −I than it gives by +R, and NO₂ withdraws by both effects, so both destabilise the cation relative to benzyl.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-goc-73", "question": "Pyrrole is a far weaker base than pyridine because:", "options": ["Its nitrogen is sp³ hybridised", "The lone pair on its nitrogen is part of the aromatic sextet, so protonating it destroys aromaticity", "It has no lone pair on nitrogen at all", "Its nitrogen carries a positive charge in the neutral molecule"], "answer": 1, "explanation": "The nitrogen of pyrrole is sp² and its lone pair occupies the p orbital that completes the 6π aromatic system; using it to bind H⁺ costs the aromatic stabilisation (pKa of conjugate acid ≈ −4). In pyridine the lone pair lies in an sp² orbital in the ring plane, outside the π system, so it is available (pKa ≈ 5.2).", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-goc-74", "question": "Which hydrocarbon is the most acidic?", "options": ["Cyclohepta-1,3,5-triene", "Propene", "Cyclopenta-1,3-diene", "Cyclopentane"], "answer": 2, "explanation": "Removing H⁺ from the CH₂ of cyclopentadiene gives the cyclopentadienyl anion, a planar 6π aromatic ion, so the pKa is about 16. Deprotonating cycloheptatriene gives an 8π (antiaromatic-type) anion; it is the cation (tropylium) of that ring that is aromatic, which is the tempting confusion.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-goc-75", "question": "Imidazole (pKa of its conjugate acid ≈ 7.0) is a stronger base than pyridine (≈ 5.2). Protonation of imidazole takes place at:", "options": ["The N–H nitrogen, because it is sp³", "A ring carbon atom, because it is the most electron-rich site", "Either nitrogen equally, because both lone pairs are in the π system", "The pyridine-type nitrogen, whose sp² lone pair is outside the aromatic sextet; the cation formed is stabilised by delocalising the charge over both nitrogens"], "answer": 3, "explanation": "The NH nitrogen's lone pair is part of the 6π system (as in pyrrole), so protonation occurs at the other N. The imidazolium ion is symmetrical, with the positive charge shared equally by both N atoms through resonance, which is why imidazole is more basic than pyridine.", "difficulty": "hard", "source": "JEE Main"},
  {"id":"chem-goc-76","question":"The correct decreasing order of Cahn–Ingold–Prelog priority of the groups –OH, –CHO, –CH₂OH and –CH(CH₃)₂ is:","options":["–OH > –CH₂OH > –CHO > –CH(CH₃)₂","–OH > –CH(CH₃)₂ > –CHO > –CH₂OH","–CHO > –OH > –CH₂OH > –CH(CH₃)₂","–OH > –CHO > –CH₂OH > –CH(CH₃)₂"],"answer":3,"explanation":"O (atomic number 8) beats any C. Among the carbon groups compare the sets of attached atoms: –CHO (O, O, H) with the C=O oxygen duplicated, –CH₂OH (O, H, H), –CH(CH₃)₂ (C, C, H). The first point of difference decides, so having more carbon atoms in total does not help isopropyl.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-77","question":"1-Cyclobutylethan-1-ol is heated with concentrated HBr. The major product is:","options":["1-Bromo-1-methylcyclopentane","1-Bromo-1-cyclobutylethane","1-Bromo-2-methylcyclopentane","(2-Bromoethyl)cyclobutane"],"answer":0,"explanation":"The secondary cation next to the strained four-membered ring undergoes ring expansion (a ring C–C bond migrates) to the 2-methylcyclopentyl cation, relieving strain; a 1,2-hydride shift then gives the tertiary 1-methylcyclopentyl cation, which captures Br⁻. Stopping after the ring expansion gives the secondary bromide, the usual trap.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-78","question":"Which one of these four carbocations is the most stable?","options":["(CH₃)₃C⁺","CH₃–O–CH₂⁺","CH₂=CH–CH₂⁺","C₆H₅–CH₂⁺"],"answer":1,"explanation":"In the methoxymethyl cation the oxygen lone pair forms a π bond to the cationic carbon (CH₃–O⁺=CH₂), a resonance form in which every atom has an octet; this +R stabilisation exceeds hyperconjugation (tert-butyl) and delocalisation into C=C or a benzene ring (allyl, benzyl), where the charge still stays on carbon.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-79","question":"The correct order of dipole moments is:","options":["CCl₄ > CHCl₃ > CH₂Cl₂ > CH₃Cl","CH₂Cl₂ > CHCl₃ > CH₃Cl > CCl₄","CH₃Cl > CH₂Cl₂ > CHCl₃ > CCl₄","CHCl₃ > CH₂Cl₂ > CH₃Cl > CCl₄"],"answer":2,"explanation":"Measured values are about 1.87, 1.60, 1.04 and 0 D. Adding more C–Cl bond moments in a tetrahedron increasingly cancels them, ending in zero for CCl₄; it is a common mistake to assume that more chlorines means a larger dipole.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-80","question":"The IUPAC name of a saturated bicyclic hydrocarbon whose two bridgehead carbons are joined by bridges of three, two and zero carbon atoms is:","options":["Bicyclo[3.2.1]octane","Bicyclo[3.2.0]pentane","Bicyclo[2.3.0]heptane","Bicyclo[3.2.0]heptane"],"answer":3,"explanation":"Total carbons = 3 + 2 + 0 + 2 bridgeheads = 7, so the parent is heptane; bridge lengths are listed in decreasing order, giving [3.2.0]. Forgetting the bridgehead atoms gives 'pentane', and [2.3.0] breaks the descending-order rule.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-81","question":"The total number of stereoisomers of pentane-2,3,4-triol, CH₃–CH(OH)–CH(OH)–CH(OH)–CH₃, is:","options":["4","8","3","6"],"answer":0,"explanation":"C2 and C4 are stereocentres. When they have the same configuration, (2R,4R) or (2S,4S), C3 carries two identical groups and is not a stereocentre: one pair of enantiomers. When they are opposite (2R,4S), C3 becomes pseudoasymmetric (r or s), giving two different meso forms. Total 2 + 2 = 4, not 2³ = 8.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id": "chem-goc-82", "question": "The correct decreasing order of CIP priority of –C≡CH, –C(CH₃)₃, –CH=CH₂ and –CH(CH₃)₂ is:", "options": ["–C(CH₃)₃ > –C≡CH > –CH(CH₃)₂ > –CH=CH₂", "–C≡CH > –C(CH₃)₃ > –CH=CH₂ > –CH(CH₃)₂", "–C(CH₃)₃ > –C≡CH > –CH=CH₂ > –CH(CH₃)₂", "–C≡CH > –CH=CH₂ > –C(CH₃)₃ > –CH(CH₃)₂"], "answer": 1, "explanation": "First atoms: –C≡CH and –C(CH₃)₃ both have (C, C, C) using duplicate atoms, and vinyl and isopropyl both have (C, C, H). Go one sphere out: the real terminal carbon of ethynyl bears (C, C, H) versus (H, H, H) on each methyl of tert-butyl, so ethynyl wins; vinyl's =CH₂ bears (C, H, H) versus (H, H, H), so vinyl beats isopropyl.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id":"chem-goc-83","question":"Arrange m-chlorophenol, p-chlorophenol, phenol and p-cresol in decreasing order of acidic strength:","options":["p-Chlorophenol > m-chlorophenol > phenol > p-cresol","m-Chlorophenol > p-chlorophenol > phenol > p-cresol","m-Chlorophenol > p-chlorophenol > p-cresol > phenol","Phenol > p-cresol > p-chlorophenol > m-chlorophenol"],"answer":1,"explanation":"pKa values are about 9.1 (meta-Cl), 9.4 (para-Cl), 10.0 (phenol) and 10.3 (p-CH₃). At the meta position Cl acts only by −I; at the para position its +R partly cancels the −I, so p-chlorophenol is weaker than the meta isomer — the opposite of the nitrophenols, where para wins because NO₂ withdraws by resonance.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-84","question":"Counting geometrical isomers separately, the number of enol forms of butan-2-one, CH₃COCH₂CH₃, is:","options":["1","2","3","4"],"answer":2,"explanation":"Enolisation towards C1 gives CH₂=C(OH)CH₂CH₃ (one form). Enolisation towards C3 gives CH₃C(OH)=CHCH₃, whose C=C has two different groups on each carbon, so it exists as E and Z. Total 1 + 2 = 3; ignoring the E/Z pair gives 2.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-85","question":"The total number of stereoisomers of 1,2-dichlorocyclobutane and 1,3-dichlorocyclobutane taken together, and how many of them are optically active, are:","options":["6 stereoisomers; 4 optically active","4 stereoisomers; 2 optically active","5 stereoisomers; 4 optically active","5 stereoisomers; 2 optically active"],"answer":3,"explanation":"1,2-isomer: cis is meso (mirror plane), trans is chiral and exists as a pair of enantiomers, so 3 stereoisomers with 2 optically active. 1,3-isomer: cis and trans both have a mirror plane through C1 and C3, so 2 stereoisomers, neither optically active. Total 5, of which 2 are optically active.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-86","question":"The number of geometrical isomers of octa-2,4,6-triene, CH₃–CH=CH–CH=CH–CH=CH–CH₃, is:","options":["6","4","8","3"],"answer":0,"explanation":"Each of the three C=C bonds can be E or Z, giving 2³ = 8 labels, but the molecule is symmetric, so (E,E,Z) is the same as (Z,E,E) and (E,Z,Z) is the same as (Z,Z,E). Distinct isomers = (8 + 4 symmetric ones)/2 = 6, i.e. 2ⁿ⁻¹ + 2ᵖ⁻¹ with n = 3, p = 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id": "chem-goc-87", "question": "How many of the following statements are correct? (A) The order of electron release by hyperconjugation (Baker–Nathan order) is CH₃– > CH₃CH₂– > (CH₃)₂CH– > (CH₃)₃C–. (B) Hyperconjugation involves delocalisation of σ(C–H) electrons into an adjacent empty p orbital or π* orbital. (C) The C2–C3 bond of propene is shorter than a normal C–C single bond, partly because of hyperconjugation. (D) The neopentyl cation, (CH₃)₃C–CH₂⁺, is stabilised by hyperconjugation more than the ethyl cation, CH₃–CH₂⁺.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are true; Baker–Nathan follows the number of α-hydrogens (3, 2, 1, 0). D is false: the α-carbon of the neopentyl cation is quaternary and carries no hydrogen, so it has no C–H hyperconjugation at all, whereas the ethyl cation has three α-hydrogens.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-goc-88", "question": "How many of the following statements are correct? (A) Both C–O bonds of the acetate ion are equal in length. (B) The C2–C3 bond of buta-1,3-diene is shorter than the C2–C3 bond of butane. (C) The C–Cl bond in chlorobenzene is longer than that in chloromethane because of resonance. (D) [10]Annulene is strongly aromatic because it has 10 π electrons.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A and B are true (resonance averages the C–O bonds; conjugation and sp²–sp² overlap shorten C2–C3). C is false: resonance gives the C–Cl bond partial double-bond character, so it is shorter (≈169 vs 177 pm). D is false: [10]annulene cannot be planar because of H–H clashes inside the ring, so despite 4n + 2 electrons it is not aromatic.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-goc-89", "question": "Singlet methylene (from photolysis of diazomethane in the liquid phase) and triplet methylene (generated in the gas phase with an inert diluent) are each added to cis-but-2-ene. The products are:", "options": ["Singlet: a mixture of cis and trans; triplet: only cis", "Both give only cis-1,2-dimethylcyclopropane", "Both give only trans-1,2-dimethylcyclopropane", "Singlet: only cis-1,2-dimethylcyclopropane; triplet: a mixture of cis- and trans-1,2-dimethylcyclopropane"], "answer": 3, "explanation": "Singlet CH₂ has paired electrons and adds in one concerted step, so the geometry of the alkene is kept (stereospecific). Triplet CH₂ is a diradical: it adds one bond at a time, and rotation about the C–C bond in the intermediate diradical (before spin inversion allows ring closure) scrambles the geometry.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-goc-90", "question": "Assertion (A): In DMSO, the order of nucleophilicity of the halide ions is F⁻ > Cl⁻ > Br⁻ > I⁻. Reason (R): In polar aprotic solvents anions are poorly solvated, so nucleophilicity follows basicity.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Protic solvents hydrogen-bond strongly to small, charge-dense F⁻, reversing the order to I⁻ > Br⁻ > Cl⁻ > F⁻. DMSO solvates cations well but leaves anions 'naked', so the more basic F⁻ becomes the best nucleophile. R is the reason for A.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-goc-91","question":"p-Bromotoluene is treated with NaNH₂ in liquid NH₃. The product is:","options":["p-Toluidine only, by direct substitution","A mixture of p-toluidine and m-toluidine","m-Toluidine only","o-Toluidine and m-toluidine"],"answer":1,"explanation":"The strong base removes the H ortho to Br and Br⁻ leaves, giving 4-methylbenzyne (the triple bond between C3 and C4). NH₂⁻ can add at either end of it, giving the amine at C4 (para to CH₃) or at C3 (meta to CH₃), so a mixture of p- and m-toluidine forms; there is no direct SNAr on an unactivated ring.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-92","question":"How many of the following molecules have zero dipole moment: trans-1,2-dichloroethene, 1,4-dichlorobenzene, hydroquinone (benzene-1,4-diol), CCl₄, trans-but-2-ene, CHCl₃?","options":["3","5","4","2"],"answer":2,"explanation":"trans-ClCH=CHCl, p-C₆H₄Cl₂, CCl₄ and trans-but-2-ene are centrosymmetric or tetrahedral, so their bond moments cancel: 4. Hydroquinone has a dipole because the O–H bonds are bent and can point to the same side (the C–O–H angle is not 180°); CHCl₃ is polar.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-93","question":"Azulene, C₁₀H₈, a fused five- and seven-membered ring hydrocarbon with 10 π electrons, has a dipole moment of about 1 D. The best explanation is:","options":["The seven-membered ring is non-planar","Azulene has a polar C–H bond that is absent in naphthalene","Electron density shifts from the five-membered ring to the seven-membered ring","Electron density shifts from the seven-membered ring to the five-membered ring, making each ring an aromatic 6π unit, like a tropylium cation fused to a cyclopentadienyl anion"],"answer":3,"explanation":"A dipolar resonance structure puts −1 on the five-membered ring (6π, like C₅H₅⁻) and +1 on the seven-membered ring (6π, like C₇H₇⁺); both rings become aromatic, so this form contributes significantly. The negative end is the five-membered ring, not the seven-membered one.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-94","question":"The correct decreasing order of acidic strength of the hydroxybenzoic acids and benzoic acid is:","options":["o-Hydroxybenzoic > m-hydroxybenzoic > benzoic > p-hydroxybenzoic","Benzoic > o-hydroxybenzoic > m-hydroxybenzoic > p-hydroxybenzoic","p-Hydroxybenzoic > m-hydroxybenzoic > o-hydroxybenzoic > benzoic","o-Hydroxybenzoic > p-hydroxybenzoic > m-hydroxybenzoic > benzoic"],"answer":0,"explanation":"pKa ≈ 3.0 (ortho), 4.1 (meta), 4.2 (benzoic), 4.5 (para). The salicylate anion is stabilised by an intramolecular hydrogen bond from the OH to COO⁻; at meta the OH acts only by −I; at para its +R pushes electron density into the ring and weakens the acid below benzoic acid.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-95","question":"The IUPAC name of HOOC–CH₂–CH(CN)–CH₂–COOH is:","options":["2-Cyanopropane-1,3-dicarboxylic acid","3-Cyanopentanedioic acid","4-Carboxy-3-cyanobutanoic acid","3-Carboxymethyl-3-cyanopropanoic acid"],"answer":1,"explanation":"Both –COOH groups can be included in the main chain (five carbons), giving pentanedioic acid; –CN, of lower priority, is a cyano substituent at C3. The 'propane-dicarboxylic acid' style is used only when the carboxyl groups cannot all be in one chain, and naming one –COOH as a carboxy substituent breaks the rule of including the principal groups in the chain.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-96","question":"The functional group present in methyl ethanoate, CH₃COOCH₃, is:","options":["Ketone","Ester","Ether","Aldehyde"],"answer":1,"explanation":"The –COO– linkage between an acyl group (CH₃CO–) and an alkoxy group (–OCH₃) defines an ester. A ketone has C=O flanked by two carbons, an ether has C–O–C without a carbonyl, and an aldehyde has –CHO.","difficulty":"easy","source":"NEET"},
  {"id":"chem-goc-97","question":"Heterolytic cleavage of the C–Br bond in (CH₃)₃C–Br produces:","options":["A carbocation and a bromide ion","Two free radicals","A carbene and HBr","A carbanion and a bromonium ion"],"answer":0,"explanation":"In heterolysis both bonding electrons go to the more electronegative atom, so Br leaves as Br⁻ and carbon is left with only six electrons: the tert-butyl carbocation. Homolysis would instead give two radicals.","difficulty":"easy","source":"NEET"},
  {"id":"chem-goc-98","question":"The IUPAC name of (CH₃)₂CH–CH₂–CH(Cl)–CH₃ is:","options":["1-Chloro-1,3-dimethylbutane","4-Chloro-2-methylpentane","2-Methyl-4-chloropentane","2-Chloro-4-methylpentane"],"answer":3,"explanation":"The longest chain has 5 carbons with substituents at C-2 and C-4 whichever end is chosen. When locants tie, the substituent cited first alphabetically (chloro before methyl) gets the lower number: 2-chloro-4-methylpentane.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-goc-99","question":"Which of the following acids is the strongest?","options":["FCH₂COOH","ClCH₂COOH","Cl₂CHCOOH","CH₃COOH"],"answer":2,"explanation":"Electron-withdrawing halogens stabilise the carboxylate by the −I effect. Two chlorines (pKa ≈ 1.3) outweigh a single fluorine (≈ 2.6) or a single chlorine (≈ 2.9); acetic acid (4.76) is weakest.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-goc-100","question":"Which of the following carbocations is the most stable?","options":["C₆H₅CH₂⁺","(C₆H₅)₃C⁺","CH₂=CH–CH₂⁺","(CH₃)₃C⁺"],"answer":1,"explanation":"The trityl cation spreads the positive charge by resonance over three phenyl rings (many contributing structures), making it so stable that its salts can be isolated. Benzyl and allyl cations have one resonance-delocalising group, and tert-butyl relies only on hyperconjugation and +I effects.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-goc-101","question":"In which of the following compounds is there NO resonance involving the heteroatom's lone pair or the substituent?","options":["CH₂=CH–CH₂–NH₂","C₆H₅NH₂","CH₂=CH–Cl","CH₂=CH–CHO"],"answer":0,"explanation":"In allylamine the CH₂ group (sp³) separates the N lone pair from the C=C, so no conjugation is possible. In vinyl chloride and aniline the lone pair is conjugated with the π system, and in acrolein the C=C is conjugated with C=O.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-goc-102","question":"Which statement about the electromeric effect is correct?","options":["It is a permanent polarisation of σ bonds","It involves delocalisation of σ electrons into an empty p orbital","It operates only in saturated compounds","It is a temporary complete transfer of π electrons that occurs only in the presence of an attacking reagent"],"answer":3,"explanation":"The electromeric effect is the temporary shift of a shared π-electron pair to one atom of a multiple bond when a reagent approaches; it disappears when the reagent is removed. Permanent σ polarisation is the inductive effect, and σ → p delocalisation is hyperconjugation.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-goc-103","question":"The correct order of decreasing acidity of CH₃COOH, C₆H₅OH, H₂O, HC≡CH and NH₃ is:","options":["CH₃COOH > H₂O > C₆H₅OH > HC≡CH > NH₃","CH₃COOH > C₆H₅OH > HC≡CH > H₂O > NH₃","CH₃COOH > C₆H₅OH > H₂O > HC≡CH > NH₃","C₆H₅OH > CH₃COOH > H₂O > NH₃ > HC≡CH"],"answer":2,"explanation":"Approximate pKa values: acetic acid 4.8, phenol 10, water 15.7, ethyne 25 and ammonia 38. Carboxylate is stabilised by two equivalent oxygens, phenoxide by the ring, and the acetylide only by sp character; the amide ion NH₂⁻ is the least stable conjugate base.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-104","question":"The number of α-hydrogen atoms available for hyperconjugation with the double bond in 2-methylbut-2-ene, (CH₃)₂C=CH–CH₃, is:","options":["10","9","6","3"],"answer":1,"explanation":"α-Hydrogens are those on carbons attached directly to the C=C. The two CH₃ groups on C-2 provide 6 and the CH₃ on C-3 provides 3, total 9. The vinylic H on C-3 is not an α-hydrogen. This large number is why trisubstituted alkenes are so stable.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-105","question":"Which of the following nitroalkanes can show tautomerism (nitro–aci-nitro)?","options":["CH₃NO₂","(CH₃)₃CNO₂","C₆H₅NO₂","CCl₃NO₂"],"answer":0,"explanation":"Nitro–aci tautomerism needs an α-hydrogen on the carbon bearing NO₂: CH₃–NO₂ ⇌ CH₂=N(O)OH. tert-Butyl nitro, nitrobenzene and chloropicrin (CCl₃NO₂) have no α-H, so they cannot tautomerise.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-106","question":"Which of the following alkanes is chiral?","options":["2-Methylbutane","2,2-Dimethylbutane","3-Methylpentane","3-Methylhexane"],"answer":3,"explanation":"In 3-methylhexane C-3 carries four different groups: H, CH₃, C₂H₅ and n-C₃H₇. In 3-methylpentane C-3 has two identical ethyl groups, in 2-methylbutane C-2 has two methyls, and 2,2-dimethylbutane has no stereocentre.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-107","question":"Which of the following is the best leaving group in nucleophilic substitution?","options":["F⁻","OH⁻","p-Toluenesulphonate (TsO⁻)","CH₃O⁻"],"answer":2,"explanation":"Good leaving groups are weak bases whose negative charge is well stabilised. Tosylate is the conjugate base of a strong sulphonic acid, with charge delocalised over three oxygens. OH⁻, CH₃O⁻ and F⁻ are much stronger bases and leave poorly, which is why alcohols are converted to tosylates before substitution.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-108","question":"Cyclopenta-1,3-diene (pKa ≈ 16) is enormously more acidic than cyclohepta-1,3,5-triene (pKa ≈ 36). The reason is:","options":["The five-membered ring is more strained","The cyclopentadienyl anion has 6 π electrons and is aromatic, while the cycloheptatrienyl anion has 8 π electrons","Cyclopentadiene has more acidic hydrogens","The CH₂ carbon of cyclopentadiene is sp hybridised"],"answer":1,"explanation":"Removing H⁺ from the sp³ CH₂ of cyclopentadiene gives a planar cyclic anion with 6 π electrons (4n + 2, n = 1), which is aromatic and highly stabilised. The cycloheptatrienyl anion would have 8 π electrons (antiaromatic if planar), so it gains no such stabilisation.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-109","question":"Chlorobenzene (1.69 D) has a smaller dipole moment than chloromethane (1.87 D) mainly because:","options":["Lone-pair donation from Cl into the ring (+M) opposes the C–Cl bond moment","The C–Cl bond in chlorobenzene is longer","Chlorine is less electronegative when bonded to sp² carbon","Benzene is larger than methane"],"answer":0,"explanation":"In chlorobenzene the −I effect of Cl is partly offset by its +M effect: lone-pair density flows into the ring, creating a moment in the opposite direction. The sp² carbon also makes the C–Cl bond shorter (partial double-bond character), not longer.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-110","question":"The C–Cl bond in vinyl chloride (CH₂=CH–Cl, about 169 pm) is shorter than that in ethyl chloride (about 178 pm) because:","options":["The C=C bond pulls the chlorine atom closer by the inductive effect alone","Vinyl chloride has a higher molar mass","Chlorine in vinyl chloride carries a positive formal charge in every structure","Resonance gives the C–Cl bond partial double-bond character and the carbon is sp² hybridised"],"answer":3,"explanation":"Delocalisation of a Cl lone pair into the π bond (CH₂⁻–CH=Cl⁺ contributor) gives partial double-bond character, and the sp² carbon (more s character) forms shorter bonds. This also explains why vinyl halides resist nucleophilic substitution.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-111","question":"Which of the following free radicals is the most stable?","options":["C₆H₅CH₂•","CH₂=CH–CH₂•","(C₆H₅)₂CH•","(CH₃)₃C•"],"answer":2,"explanation":"The diphenylmethyl radical delocalises the unpaired electron over two benzene rings, giving more resonance structures than the benzyl or allyl radicals. The tert-butyl radical is stabilised only by hyperconjugation and is the least stable here.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-112","question":"(2R,3S)-2,3-Dibromopentane and (2S,3R)-2,3-dibromopentane are:","options":["Identical (a meso compound)","Enantiomers","Structural isomers","Diastereomers"],"answer":1,"explanation":"Inverting every stereocentre gives the mirror image. Because 2,3-dibromopentane has different ends (CH₃ and C₂H₅), there is no internal mirror plane, so (2R,3S) and (2S,3R) are non-superimposable mirror images: enantiomers. A meso form arises only with identical ends, as in 2,3-dibromobutane.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-113","question":"Dichlorocarbene, generated from CHCl₃ and KOH, is best described as:","options":["A neutral, electron-deficient (electrophilic) singlet carbene","A carbocation with a positive charge on carbon","A nucleophilic carbanion","A free radical with three unpaired electrons"],"answer":0,"explanation":"CHCl₃ + OH⁻ → CCl₃⁻ → :CCl₂ + Cl⁻ (α-elimination). The carbon has only six valence electrons (a lone pair and two bonds) and an empty p orbital, so it is neutral but electrophilic; its singlet state is favoured by back-donation from the Cl lone pairs. It is the intermediate in the Reimer–Tiemann reaction.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-114","question":"The number of hyperconjugative structures (including C–H no-bond resonance forms only) possible for the isopropyl cation, (CH₃)₂CH⁺, is:","options":["3","7","2","6"],"answer":3,"explanation":"Each C–H bond on a carbon adjacent to the cationic centre can donate into the empty p orbital. The two CH₃ groups provide 6 α-hydrogens, giving 6 hyperconjugative (no-bond) structures. The tert-butyl cation, with 9 α-H, is more stabilised.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-goc-115","question":"The total number of stereoisomers of 1,3-dimethylcyclobutane is:","options":["4","1","2","3"],"answer":2,"explanation":"There are cis and trans isomers. Each has a mirror plane passing through C-1 and C-3 (and their methyl groups), so neither is chiral and C-1/C-3 are not stereocentres in the R/S sense. Hence only 2 stereoisomers, both achiral, unlike 1,2-dimethylcyclobutane, which has a chiral trans pair.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-goc-116","question":"The number of geometrical isomers of hexa-2,4-diene, CH₃–CH=CH–CH=CH–CH₃, is:","options":["6","3","4","2"],"answer":1,"explanation":"Each double bond can be E or Z, giving EE, ZZ, EZ and ZE. Because the molecule has identical ends, EZ and ZE are the same compound. Hence 3 geometrical isomers. A diene with different ends (e.g. hepta-2,4-diene) would have 4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-117","question":"Which of the following species is antiaromatic (if planar)?","options":["Cyclopropenyl anion","Cyclopropenyl cation","Cycloheptatrienyl (tropylium) cation","Cyclononatetraenyl anion"],"answer":0,"explanation":"A planar, cyclic, fully conjugated ring with 4n π electrons is antiaromatic. The cyclopropenyl anion has 4 π electrons (n = 1). The cyclopropenyl cation (2), tropylium (6) and the cyclononatetraenyl anion (10) all have 4n + 2 π electrons and are aromatic.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-118","question":"The correct order of acid strength of benzoic acid, m-methoxybenzoic acid and p-methoxybenzoic acid is:","options":["benzoic > m-methoxy > p-methoxy","p-methoxy > m-methoxy > benzoic","p-methoxy > benzoic > m-methoxy","m-methoxy > benzoic > p-methoxy"],"answer":3,"explanation":"From the meta position OCH₃ cannot donate by resonance to the carboxyl-bearing carbon, so only its −I effect acts and the acid is stronger (pKa 4.09) than benzoic acid (4.20). From the para position the +M effect dominates and destabilises the carboxylate, so p-methoxybenzoic acid is weaker (4.47).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-119","question":"Among benzoic acid and the three isomeric toluic (methylbenzoic) acids, the strongest acid is:","options":["m-Toluic acid","Benzoic acid","o-Toluic acid (2-methylbenzoic acid)","p-Toluic acid"],"answer":2,"explanation":"Although CH₃ is electron-donating, an ortho substituent twists the COOH group out of the ring plane, removing the ring's resonance donation into the carboxyl group (the ortho effect). So o-toluic acid (pKa 3.9) is stronger than benzoic acid (4.2), while m- (4.27) and p-toluic acids (4.37) are weaker.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-120","question":"In a polar aprotic solvent such as DMSO or DMF, the most nucleophilic halide ion is:","options":["I⁻","F⁻","Br⁻","Cl⁻"],"answer":1,"explanation":"Aprotic solvents cannot hydrogen-bond to anions, so the halides are 'naked' and nucleophilicity follows basicity: F⁻ > Cl⁻ > Br⁻ > I⁻. In protic solvents strong solvation of F⁻ reverses this order.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-121","question":"The correct IUPAC name of CH₂=CH–CH(OH)–CH₂–C≡CH is:","options":["Hex-1-en-5-yn-3-ol","Hex-1-yn-5-en-4-ol","Hex-5-yn-1-en-3-ol","Hex-5-en-1-yn-4-ol"],"answer":0,"explanation":"The –OH is the principal group, so the chain is numbered to give it the lowest locant: starting from the CH₂= end puts OH at C-3 (from the other end it would be C-4). Then the C=C is at 1 and the C≡C at 5, and 'en' is cited before 'yn': hex-1-en-5-yn-3-ol.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-122","question":"The number of structurally isomeric trisubstituted benzenes of formula C₆H₃Cl₂Br is:","options":["10","3","4","6"],"answer":3,"explanation":"For a benzene with two identical substituents (Cl, Cl) and one different (Br): Cl's 1,2 gives two (Br at 3 or 4), Cl's 1,3 gives three (Br at 2, 4 or 5), and Cl's 1,4 gives one (Br at 2). Total 6. Three identical substituents would give only 3.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-goc-123","question":"The 3,3-dimethylbutan-2-yl cation, (CH₃)₃C–CH⁺–CH₃, formed during a reaction, rapidly rearranges to:","options":["The 3,3-dimethylbutan-1-yl cation by a 1,2-hydride shift","The tert-butyl cation and ethene","The 2,3-dimethylbutan-2-yl cation, (CH₃)₂C⁺–CH(CH₃)₂, by a 1,2-methyl shift","No rearrangement, since it is already tertiary"],"answer":2,"explanation":"The initial cation is secondary. Migration of a methyl group (with its bonding pair) from the adjacent quaternary carbon gives a tertiary cation, which is more stable. This methyl shift explains the rearranged products in, for example, dehydration of 3,3-dimethylbutan-2-ol.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-124","question":"In ethyl acetoacetate, CH₃–CO–CH₂–CO–OC₂H₅, the most acidic hydrogen atoms are those of the:","options":["CH₂ of the ethyl group","CH₂ group between the two carbonyl groups","CH₃ of the ethyl group","CH₃ group attached to the ketone"],"answer":1,"explanation":"The central CH₂ (pKa ≈ 11) is flanked by two carbonyls, so its conjugate base is delocalised onto both oxygens. The ketone CH₃ (pKa ≈ 20) is activated by only one C=O, and the ethoxy hydrogens are not activated at all.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-goc-125","question":"The correct order of basicity of piperidine, pyridine and pyrrole is:","options":["Piperidine > pyridine > pyrrole","Piperidine > pyrrole > pyridine","Pyridine > piperidine > pyrrole","Pyrrole > pyridine > piperidine"],"answer":0,"explanation":"Piperidine's N lone pair is in an sp³ orbital (pKa of conjugate acid ≈ 11.1). Pyridine's lone pair is in an sp² orbital with more s character, held more tightly (≈ 5.2). In pyrrole the lone pair is part of the aromatic sextet, so protonation destroys aromaticity and it is an extremely weak base.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-126","question":"Which conformation is the most stable for ethane-1,2-diol (ethylene glycol) about its C–C bond?","options":["Anti, because the OH groups are farthest apart","Eclipsed, because the OH groups can share electrons","All conformations have equal energy","Gauche, because of intramolecular hydrogen bonding between the two OH groups"],"answer":3,"explanation":"For butane the anti conformer is most stable, but in ethylene glycol the gauche conformer allows an O–H···O hydrogen bond between the adjacent OH groups, which outweighs the small gauche repulsion. This is a common exception to steric expectations.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-goc-127","question":"A pure enantiomer of a compound has specific rotation −23.0°. A sample of the compound shows a specific rotation of −4.6°. The percentage of the (−)-enantiomer in the sample is:","options":["80%","40%","60%","20%"],"answer":2,"explanation":"Enantiomeric excess = observed/pure = 4.6/23.0 = 20% in favour of (−). So (−) − (+) = 20% and (−) + (+) = 100%, giving (−) = 60% and (+) = 40%. 20% is the excess, not the composition.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-goc-128","question":"The number of structural (constitutional) isomers of molecular formula C₄H₁₀O is:","options":["8","7","4","3"],"answer":1,"explanation":"Alcohols: butan-1-ol, butan-2-ol, 2-methylpropan-1-ol and 2-methylpropan-2-ol (4). Ethers: 1-methoxypropane, 2-methoxypropane and ethoxyethane (3). Total 7; counting the two enantiomers of butan-2-ol separately would give 8 stereoisomers in all.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-goc-129","question":"The correct order of acidity of the following alcohols in solution is:","options":["CH₃OH > CH₃CH₂OH > (CH₃)₂CHOH > (CH₃)₃COH","(CH₃)₃COH > (CH₃)₂CHOH > CH₃CH₂OH > CH₃OH","CH₃CH₂OH > CH₃OH > (CH₃)₃COH > (CH₃)₂CHOH","All four are equally acidic"],"answer":0,"explanation":"Bulky alkyl groups hinder solvation of the alkoxide ion, and their +I effect destabilises it further. Methoxide is the best solvated, so methanol is the most acidic (pKa ≈ 15.5) and tert-butanol the least (≈ 18).","difficulty":"very-hard","source":"JEE Main"},
];

export default questions;
